/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def channel_ingress_and_pii_sanitizer(input_data: dict) -> dict:
    """
    تطبيع الرسائل الواردة من جميع القنوات (واتساب، تيليجرام، بريد، ويب شات)
    وإخفاء البيانات الشخصية الحساسة (رقم قومي، بطاقة ائتمان، IBAN).

    Normalizes incoming messages from all channels and masks sensitive PII
    for PDPL (Personal Data Protection Law) compliance.

    Args:
        input_data: Raw webhook payload from any channel.

    Returns:
        Normalized dict with unified fields and PII masking applied.
    """
    body = input_data.get("body", input_data)

    channel = body.get("channel", "webchat")
    customer_message = ""
    phone_number = ""
    telegram_id = ""
    email = ""
    full_name = ""
    channel_user_id = ""

    # 1. Meta WhatsApp Webhook Detection
    entry = body.get("entry", [])
    if entry and entry[0].get("changes", [{}])[0].get("value", {}).get("messages"):
        channel = "whatsapp"
        val = entry[0]["changes"][0]["value"]
        msg = val["messages"][0]
        customer_message = (
            msg.get("text", {}).get("body")
            or msg.get("interactive", {}).get("button_reply", {}).get("title")
            or "Hello"
        )
        phone_number = "+" + msg.get("from", "")
        channel_user_id = phone_number
        contacts = val.get("contacts", [{}])
        full_name = contacts[0].get("profile", {}).get("name", "WhatsApp User") if contacts else "WhatsApp User"

    # 1b. Direct / Baileys / Evolution WhatsApp Ingress
    elif body.get("channel") == "whatsapp" or (
        body.get("event") == "messages.upsert" and body.get("data", {}).get("message")
    ) or body.get("data", {}).get("key", {}).get("remoteJid"):
        channel = "whatsapp"
        data = body.get("data", body)
        msg = data.get("message", {})
        customer_message = (
            body.get("customer_message")
            or msg.get("conversation")
            or msg.get("extendedTextMessage", {}).get("text")
            or body.get("message")
            or "Hello"
        )
        remote_jid = data.get("key", {}).get("remoteJid", "")
        raw_phone = remote_jid.split("@")[0] if remote_jid else (
            body.get("phone_number") or body.get("phone") or ""
        )
        phone_number = raw_phone if raw_phone.startswith("+") else (
            "+" + re.sub(r"[^0-9]", "", raw_phone) if raw_phone else "+966500000000"
        )
        channel_user_id = phone_number
        full_name = body.get("full_name") or data.get("pushName") or "WhatsApp Citizen"

    # 2. Telegram Bot Webhook
    elif body.get("message", {}).get("chat"):
        channel = "telegram"
        customer_message = body["message"].get("text", "مرحبا")
        from_user = body["message"].get("from", {})
        telegram_id = str(from_user.get("id") or body["message"]["chat"].get("id", ""))
        channel_user_id = telegram_id
        parts = [from_user.get("first_name", ""), from_user.get("last_name", "")]
        full_name = " ".join(filter(None, parts)) or from_user.get("username", "Telegram Citizen")

    # 3. Email Ingress
    elif body.get("from") and (body.get("subject") or body.get("body")):
        channel = "email"
        customer_message = body.get("body") or body.get("message") or body.get("subject") or ""
        email = body["from"]
        channel_user_id = email
        full_name = body.get("name") or email.split("@")[0]

    # 4. Webchat / Direct REST API
    else:
        customer_message = body.get("customer_message") or body.get("message") or "مرحبا، أود الاستفسار"
        phone_number = body.get("phone") or body.get("phone_number") or ""
        telegram_id = body.get("telegram_id") or ""
        email = body.get("email") or ""
        full_name = body.get("name") or body.get("full_name") or "Valued Citizen"
        channel_user_id = phone_number or telegram_id or email or "web-anon"

    # 5. PII Masking (PDPL Compliance)
    sanitized_message = customer_message
    pii_detected = False

    # Saudi National ID (10 digits starting with 1 or 2)
    if re.search(r"\b[12]\d{9}\b", sanitized_message):
        sanitized_message = re.sub(r"\b[12]\d{9}\b", "[NATIONAL_ID_MASKED]", sanitized_message)
        pii_detected = True

    # Credit Card numbers
    if re.search(r"\b(?:\d{4}[ -]?){3}\d{4}\b", sanitized_message):
        sanitized_message = re.sub(r"\b(?:\d{4}[ -]?){3}\d{4}\b", "[CARD_MASKED]", sanitized_message)
        pii_detected = True

    # Saudi IBANs
    if re.search(r"\bSA\d{2}[0-9A-Za-z]{20}\b", sanitized_message):
        sanitized_message = re.sub(r"\bSA\d{2}[0-9A-Za-z]{20}\b", "[IBAN_MASKED]", sanitized_message)
        pii_detected = True

    # Language Detection
    is_arabic = bool(re.search(r"[\u0600-\u06FF]", customer_message))
    locale = "ar" if is_arabic else "en"

    return {
        "channel": channel,
        "channel_user_id": channel_user_id,
        "customer_message": customer_message,
        "sanitized_message": sanitized_message,
        "pii_detected": pii_detected,
        "phone_number": phone_number,
        "telegram_id": telegram_id,
        "email": email,
        "full_name": full_name,
        "locale": locale,
        "start_time": int(datetime.now(timezone.utc).timestamp() * 1000),
    }


# ==============================================================================
# 2. WORKFLOW 02 — Compile Session Context
# Node: "Compile Session Context"
# Purpose: Merges customer profile, conversation data, and history into a
#          single context object for downstream AI processing.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const input = $input.first()?.json || {};
const body = input.body || input;

let channel = body.channel || 'webchat';
let customerMessage = '';
let phoneNumber = '';
let telegramId = '';
let email = '';
let fullName = '';
let channelUserId = '';

// 1. Meta WhatsApp Webhook Detection
if (body.entry && body.entry[0]?.changes && body.entry[0].changes[0]?.value?.messages) {
  channel = 'whatsapp';
  const val = body.entry[0].changes[0].value;
  const msg = val.messages[0];
  customerMessage = msg.text?.body || msg.interactive?.button_reply?.title || 'Hello';
  phoneNumber = '+' + msg.from;
  channelUserId = phoneNumber;
  fullName = val.contacts?.[0]?.profile?.name || 'WhatsApp User';
}

// 1b. Direct / Baileys / Evolution WhatsApp Ingress Detection
else if (body.channel === 'whatsapp' || (body.event === 'messages.upsert' && body.data?.message) || body.data?.key?.remoteJid) {
  channel = 'whatsapp';
  const data = body.data || body;
  const msg = data.message || {};
  customerMessage = body.customer_message || msg.conversation || msg.extendedTextMessage?.text || body.message || 'Hello';
  const rawPhone = (data.key?.remoteJid ? data.key.remoteJid.split('@')[0] : (body.phone_number || body.phone || ''));
  phoneNumber = rawPhone ? (rawPhone.startsWith('+') ? rawPhone : ('+' + rawPhone.replace(/[^0-9]/g, ''))) : '+966500000000';
  channelUserId = phoneNumber;
  fullName = body.full_name || data.pushName || 'WhatsApp Citizen';
}
// 2. Telegram Bot Webhook Detection
else if (body.message && body.message.chat) {
  channel = 'telegram';
  customerMessage = body.message.text || 'مرحبا';
  telegramId = String(body.message.from?.id || body.message.chat.id);
  channelUserId = telegramId;
  fullName = [body.message.from?.first_name, body.message.from?.last_name].filter(Boolean).join(' ') || body.message.from?.username || 'Telegram Citizen';
}
// 3. Email Ingress Detection
else if (body.from && (body.subject || body.body)) {
  channel = 'email';
  customerMessage = body.body || body.message || body.subject || '';
  email = body.from;
  channelUserId = email;
  fullName = body.name || email.split('@')[0];
}
// 4. Webchat / Direct REST API
else {
  customerMessage = body.customer_message || body.message || 'مرحبا، أود الاستفسار عن حالة طلبي SRV-1001';
  phoneNumber = body.phone || body.phone_number || '';
  telegramId = body.telegram_id || '';
  email = body.email || '';
  fullName = body.name || body.full_name || 'Valued Citizen';
  channelUserId = phoneNumber || telegramId || email || 'web-anon';
}

// 5. MCIT Compliance: PII Masking & Language Detection
let sanitizedMessage = customerMessage;
let piiDetected = false;

// Saudi National ID (10 digits starting with 1 or 2) & Egyptian National ID (14 digits starting with 2 or 3)
if (/\b[12]\d{9}\b/.test(sanitizedMessage) || /\b[23]\d{13}\b/.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\b[12]\d{9}\b/g, '[NATIONAL_ID_MASKED]').replace(/\b[23]\d{13}\b/g, '[NATIONAL_ID_MASKED]');
  piiDetected = true;
}

// Credit Card numbers
if (/\b(?:\d{4}[ -]?){3}\d{4}\b/.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\b(?:\d{4}[ -]?){3}\d{4}\b/g, '[CARD_MASKED]');
  piiDetected = true;
}

// Saudi IBANs
if (/\bSA\d{2}[0-9A-Z]{20}\b/i.test(sanitizedMessage)) {
  sanitizedMessage = sanitizedMessage.replace(/\bSA\d{2}[0-9A-Z]{20}\b/gi, '[IBAN_MASKED]');
  piiDetected = true;
}

// Language Detection (Arabic block)
const isArabic = /[\u0600-\u06FF]/.test(customerMessage);
const locale = isArabic ? 'ar' : 'en';

return [{
  json: {
    channel: channel,
    channel_user_id: channelUserId,
    customer_message: customerMessage,
    sanitized_message: sanitizedMessage,
    pii_detected: piiDetected,
    phone_number: phoneNumber,
    telegram_id: telegramId,
    email: email,
    full_name: fullName,
    locale: locale,
    start_time: Date.now()
  }
}];
